#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) scanf("%d", &a[i]);

    int low = 0, i = 0, high = n - 1;
    while (i <= high) {
        if (a[i] == 0) {
            std::swap(a[low], a[i]);
            ++low; ++i;
        } else if (a[i] == 1) {
            ++i;
        } else {
            std::swap(a[i], a[high]);
            --high;                       // i 不动！换来的元素尚未检查
        }
    }

    for (int j = 0; j < n; ++j) {
        if (j) printf(" ");
        printf("%d", a[j]);
    }
    printf("\n");
    return 0;
}
